<?php

namespace App\Http\Controllers\Api\V1;

use App\Mail\SupplierPortalInvitationMail;
use App\Models\{Company, PurchaseOrder, PurchaseOrderItem, Supplier, SupplierAdvanceShippingNotice, SupplierAsnLine, SupplierCorrectiveAction, SupplierCorrectiveActionResponse, SupplierDeliveryCommitment, SupplierInvoiceSubmission, SupplierPoAcknowledgement, SupplierPortalConversation, SupplierPortalInvitation, SupplierPortalMembership, SupplierPortalMessage};
use App\Services\{AuditLogger, AuthorizationService, ProcurementNumberService};
use App\Support\TenantContext;
use Illuminate\Http\{JsonResponse, Request};
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;

final class SupplierPortalController
{
    private function tenant(): string { return (string) app(TenantContext::class)->id(); }
    private function internal(Request $r, AuthorizationService $a, string $company): void { abort_unless($a->allows($r->user(),$this->tenant(),'procurement.manage',$company),403); }
    private function membership(Request $r, ?string $company=null): SupplierPortalMembership
    {
        $q=SupplierPortalMembership::where('user_id',$r->user()->id)->where('status','active')->whereHas('supplier',fn($s)=>$s->where('status','active'))->with(['supplier','company']);
        if($company)$q->where('company_id',$company);
        $m=$q->first();abort_unless($m,403,'No active supplier portal membership exists for this account.');return $m;
    }
    public function access(Request $r, AuthorizationService $a): JsonResponse
    {
        $company=$r->string('company_id')->toString()?:null;if($company)$this->internal($r,$a,$company);$q=SupplierPortalMembership::where('tenant_id',$this->tenant())->with(['supplier','company','user'])->when($company,fn($x)=>$x->where('company_id',$company))->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))->latest();$inv=SupplierPortalInvitation::where('tenant_id',$this->tenant())->when($company,fn($x)=>$x->where('company_id',$company))->where('status','pending')->count();return response()->json(['data'=>$q->paginate(25),'pending_invitations'=>$inv]);
    }
    public function invite(Request $r, AuthorizationService $a, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','email'=>'required|email|max:255','role'=>'required|in:admin,sales,logistics,documents,read_only','expires_in_days'=>'nullable|integer|min:1|max:30']);$this->internal($r,$a,$d['company_id']);$t=$this->tenant();$s=Supplier::where('tenant_id',$t)->whereKey($d['supplier_id'])->where('status','active')->firstOrFail();abort_unless($s->company_id===null||$s->company_id===$d['company_id'],422);$email=strtolower(trim($d['email']));abort_if(SupplierPortalInvitation::where('tenant_id',$t)->where('supplier_id',$s->id)->where('company_id',$d['company_id'])->where('email',$email)->where('status','pending')->where('expires_at','>',now())->exists(),422,'A pending portal invitation already exists.');$token=Str::random(64);$i=SupplierPortalInvitation::create(['tenant_id'=>$t,'supplier_id'=>$s->id,'company_id'=>$d['company_id'],'email'=>$email,'role'=>$d['role'],'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addDays($d['expires_in_days']??7),'invited_by'=>$r->user()->id]);try{Mail::to($email)->send(new SupplierPortalInvitationMail($i->load('company'),$token));}catch(\Throwable $e){$audit->record($r,'supplier_portal.invitation.delivery_failed',$t,$i,['company_id'=>$d['company_id']]);return response()->json(['message'=>'Invitation was created, but the configured mail provider could not accept it.','invitation_id'=>$i->id],503);}$audit->record($r,'supplier_portal.invitation.created',$t,$i,['company_id'=>$d['company_id'],'supplier_id'=>$s->id]);return response()->json(['data'=>$i,'delivery'=>'accepted_by_mailer'],201);
    }
    public function revokeInvitation(Request $r,SupplierPortalInvitation $invitation,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($invitation->tenant_id===$this->tenant(),404);$this->internal($r,$a,$invitation->company_id);abort_unless($invitation->status==='pending',422);$invitation->update(['status'=>'revoked','revoked_at'=>now(),'token_hash'=>hash('sha256',Str::random(64))]);$audit->record($r,'supplier_portal.invitation.revoked',$this->tenant(),$invitation);return response()->json(['data'=>$invitation]);}
    public function acceptInvitation(Request $r, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['token'=>'required|string']);$i=SupplierPortalInvitation::where('token_hash',hash('sha256',$d['token']))->firstOrFail();abort_unless($i->status==='pending'&&!$i->expires_at->isPast(),410,'Invitation is no longer valid.');abort_unless(strtolower($r->user()->email)===strtolower($i->email),403,'Invitation email does not match this account.');$m=DB::transaction(function()use($i,$r,$audit){$locked=SupplierPortalInvitation::whereKey($i->id)->lockForUpdate()->firstOrFail();abort_unless($locked->status==='pending'&&!$locked->expires_at->isPast(),410);$m=SupplierPortalMembership::updateOrCreate(['tenant_id'=>$locked->tenant_id,'supplier_id'=>$locked->supplier_id,'company_id'=>$locked->company_id,'user_id'=>$r->user()->id],['role'=>$locked->role,'status'=>'active','created_by'=>$locked->invited_by]);$locked->update(['status'=>'accepted','accepted_user_id'=>$r->user()->id,'accepted_at'=>now(),'token_hash'=>hash('sha256',Str::random(64))]);$audit->record($r,'supplier_portal.invitation.accepted',$locked->tenant_id,$m);return $m;});return response()->json(['data'=>$m->load(['supplier','company'])]);
    }
    public function me(Request $r): JsonResponse { $m=$this->membership($r);$m->update(['last_login_at'=>now()]);return response()->json(['data'=>['membership'=>$m->load(['supplier','company']),'user'=>$r->user()->only(['id','name','email'])]]); }
    public function dashboard(Request $r): JsonResponse
    {
        $m=$this->membership($r);$po=$this->poQuery($m);$conversations=SupplierPortalConversation::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id);$actions=SupplierCorrectiveAction::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->whereIn('status',['open','in_progress','pending_verification']);return response()->json(['data'=>['supplier'=>$m->supplier,'company'=>$m->company,'open_purchase_orders'=>(clone $po)->count(),'awaiting_acknowledgement'=> (clone $po)->whereDoesntHave('supplierPortalAcknowledgements')->count(),'upcoming_deliveries'=>(clone $po)->whereNotNull('expected_at')->whereBetween('expected_at',[now()->toDateString(),now()->addDays(30)->toDateString()])->count(),'submitted_shipments'=>SupplierAdvanceShippingNotice::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->whereIn('status',['submitted','accepted_for_receiving'])->count(),'open_corrective_actions'=>$actions->count(),'conversations'=>$conversations->count()]]);
    }
    public function purchaseOrders(Request $r): JsonResponse { $m=$this->membership($r);$q=$this->poQuery($m)->with(['items.variant.product','currency','branch'])->when($r->filled('search'),fn($x)=>$x->where('number','ilike','%'.$r->string('search').'%'))->latest('order_date');return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]); }
    public function purchaseOrder(Request $r,PurchaseOrder $order): JsonResponse { $m=$this->membership($r);abort_unless((string)$order->tenant_id===$m->tenant_id&&$order->supplier_id===$m->supplier_id&&$order->company_id===$m->company_id&&in_array($order->state,['approved','partially_received','received','closed'],true),404);return response()->json(['data'=>['id'=>$order->id,'number'=>$order->number,'order_date'=>$order->order_date,'expected_at'=>$order->expected_at,'currency'=>$order->currency?->only(['code','decimal_places']),'supplier'=>$m->supplier->only(['id','name','code']),'items'=>$order->items()->with(['variant.product'])->get()->map(fn($i)=>['id'=>$i->id,'product'=>$i->variant?->product?->name,'sku'=>$i->supplier_sku_snapshot??$i->variant?->sku,'description'=>$i->description,'quantity'=>$i->ordered_quantity,'uom'=>$i->purchase_uom_snapshot,'unit_price'=>$i->unit_price,'line_total'=>$i->line_total]),'notes'=>$order->notes,'payment_terms'=>$order->payment_terms]]);
    }
    public function acknowledge(Request $r,PurchaseOrder $order,AuditLogger $audit):JsonResponse { $m=$this->membership($r);abort_unless($this->released($order,$m),404);$d=$r->validate(['type'=>'required|in:acknowledged,discrepancy,clarification','notes'=>'nullable|string|max:4000','idempotency_key'=>'required|string|max:100']);$x=SupplierPoAcknowledgement::firstOrCreate(['tenant_id'=>$m->tenant_id,'purchase_order_id'=>$order->id,'idempotency_key'=>$d['idempotency_key']],['supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'user_id'=>$r->user()->id,'type'=>$d['type'],'notes'=>$d['notes']??null,'po_version'=>$order->updated_at?->toISOString(),'acknowledged_at'=>now()]);$audit->record($r,'supplier_portal.po_acknowledged',$m->tenant_id,$x,['company_id'=>$m->company_id]);return response()->json(['data'=>$x]);}
    public function commitments(Request $r):JsonResponse{$m=$this->membership($r);$q=SupplierDeliveryCommitment::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->latest();return response()->json(['data'=>$q->paginate(25)]);}
    public function createCommitment(Request $r,AuditLogger $audit):JsonResponse{$m=$this->membership($r);$d=$r->validate(['purchase_order_id'=>'required|uuid','purchase_order_item_id'=>'required|uuid','proposed_delivery_date'=>'required|date','proposed_quantity'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'delivery_location'=>'nullable|string|max:255','shipment_method'=>'nullable|string|max:100','supplier_notes'=>'nullable|string|max:4000']);$o=PurchaseOrder::whereKey($d['purchase_order_id'])->firstOrFail();abort_unless($this->released($o,$m),404);$item=$o->items()->whereKey($d['purchase_order_item_id'])->firstOrFail();$existing=(float)SupplierDeliveryCommitment::where('purchase_order_item_id',$item->id)->whereIn('status',['proposed','under_review','accepted'])->sum('proposed_quantity');abort_unless($existing+(float)$d['proposed_quantity']<=(float)$item->ordered_quantity-(float)$item->received_quantity,422,'Commitments exceed the remaining PO quantity.');$x=SupplierDeliveryCommitment::create([...$d,'tenant_id'=>$m->tenant_id,'supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'version'=>1,'status'=>'proposed','created_by'=>$r->user()->id]);$audit->record($r,'supplier_portal.delivery_commitment.proposed',$m->tenant_id,$x);return response()->json(['data'=>$x],201);}
    public function shipments(Request $r):JsonResponse{$m=$this->membership($r);$q=SupplierAdvanceShippingNotice::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->with('lines')->latest();return response()->json(['data'=>$q->paginate(25)]);}
    public function createShipment(Request $r,ProcurementNumberService $numbers,AuditLogger $audit):JsonResponse{$m=$this->membership($r);$d=$r->validate(['purchase_order_id'=>'required|uuid','planned_dispatch_date'=>'nullable|date','expected_arrival_date'=>'nullable|date|after_or_equal:planned_dispatch_date','carrier'=>'nullable|string|max:160','tracking_reference'=>'nullable|string|max:160','package_count'=>'nullable|integer|min:1','package_details'=>'nullable|string|max:4000','notes'=>'nullable|string|max:4000','idempotency_key'=>'required|string|max:100','lines'=>'required|array|min:1','lines.*.purchase_order_item_id'=>'required|uuid','lines.*.expected_shipped_quantity'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'lines.*.uom'=>'nullable|string|max:40','lines.*.batch_reference'=>'nullable|string|max:160','lines.*.serial_references'=>'nullable|array']);$o=PurchaseOrder::whereKey($d['purchase_order_id'])->firstOrFail();abort_unless($this->released($o,$m),404);abort_if(SupplierAdvanceShippingNotice::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('idempotency_key',$d['idempotency_key'])->exists(),409,'This shipment notice was already submitted.');$asn=DB::transaction(function()use($d,$m,$r,$numbers){$asn=SupplierAdvanceShippingNotice::create(['tenant_id'=>$m->tenant_id,'supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'purchase_order_id'=>$d['purchase_order_id'],'number'=>$numbers->makeFor('ASN',$m->tenant_id,$m->company_id,null),'planned_dispatch_date'=>$d['planned_dispatch_date']??null,'expected_arrival_date'=>$d['expected_arrival_date']??null,'carrier'=>$d['carrier']??null,'tracking_reference'=>$d['tracking_reference']??null,'package_count'=>$d['package_count']??null,'package_details'=>$d['package_details']??null,'notes'=>$d['notes']??null,'status'=>'submitted','idempotency_key'=>$d['idempotency_key'],'created_by'=>$r->user()->id]);foreach($d['lines'] as $line){$item=PurchaseOrderItem::whereKey($line['purchase_order_item_id'])->where('purchase_order_id',$asn->purchase_order_id)->firstOrFail();abort_unless((float)$line['expected_shipped_quantity']<=(float)$item->ordered_quantity-(float)$item->received_quantity,422,'Shipment quantity exceeds remaining PO quantity.');SupplierAsnLine::create([...$line,'tenant_id'=>$m->tenant_id,'asn_id'=>$asn->id]);}return $asn;});$audit->record($r,'supplier_portal.asn.submitted',$m->tenant_id,$asn);return response()->json(['data'=>$asn->load('lines')],201);}
    public function invoiceSubmissions(Request $r):JsonResponse{$m=$this->membership($r);return response()->json(['data'=>SupplierInvoiceSubmission::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->latest()->paginate(25)]);}
    public function createInvoiceSubmission(Request $r,AuditLogger $audit):JsonResponse{$m=$this->membership($r);$d=$r->validate(['purchase_order_id'=>'nullable|uuid','supplier_invoice_number'=>'required|string|max:160','invoice_date'=>'required|date','currency_id'=>'nullable|uuid','claimed_total'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'notes'=>'nullable|string|max:4000','idempotency_key'=>'required|string|max:100']);if($d['purchase_order_id']??null){$o=PurchaseOrder::whereKey($d['purchase_order_id'])->firstOrFail();abort_unless($this->released($o,$m),404);}abort_if(SupplierInvoiceSubmission::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->where('supplier_invoice_number',$d['supplier_invoice_number'])->exists(),422,'This supplier invoice number has already been submitted.');$x=SupplierInvoiceSubmission::create([...$d,'tenant_id'=>$m->tenant_id,'supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'status'=>'submitted','created_by'=>$r->user()->id]);$audit->record($r,'supplier_portal.invoice_submitted',$m->tenant_id,$x);return response()->json(['data'=>$x],201);}
    public function conversations(Request $r):JsonResponse{$m=$this->membership($r);$q=SupplierPortalConversation::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->with('messages')->latest();return response()->json(['data'=>$q->paginate(25)]);}
    public function createConversation(Request $r):JsonResponse{$m=$this->membership($r);$d=$r->validate(['subject'=>'required|string|max:200','type'=>'required|in:general,purchase_order,delivery,shipment,document,invoice,corrective_action','body'=>'required|string|max:10000']);$c=DB::transaction(function()use($d,$m,$r){$c=SupplierPortalConversation::create(['tenant_id'=>$m->tenant_id,'supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'subject'=>$d['subject'],'type'=>$d['type']]);SupplierPortalMessage::create(['tenant_id'=>$m->tenant_id,'conversation_id'=>$c->id,'sender_id'=>$r->user()->id,'body'=>$d['body'],'visibility'=>'external']);return $c;});return response()->json(['data'=>$c->load('messages')],201);}
    public function sendMessage(Request $r,SupplierPortalConversation $conversation,AuditLogger $audit):JsonResponse{$m=$this->membership($r);abort_unless($conversation->tenant_id===$m->tenant_id&&$conversation->supplier_id===$m->supplier_id&&$conversation->company_id===$m->company_id,404);$d=$r->validate(['body'=>'required|string|max:10000']);$x=SupplierPortalMessage::create(['tenant_id'=>$m->tenant_id,'conversation_id'=>$conversation->id,'sender_id'=>$r->user()->id,'body'=>$d['body'],'visibility'=>'external']);$audit->record($r,'supplier_portal.message.sent',$m->tenant_id,$x);return response()->json(['data'=>$x],201);}
    public function actions(Request $r):JsonResponse{$m=$this->membership($r);$q=SupplierCorrectiveAction::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->whereIn('status',['open','in_progress','pending_verification'])->latest();return response()->json(['data'=>$q->paginate(25)]);}
    public function respondAction(Request $r,SupplierCorrectiveAction $action,AuditLogger $audit):JsonResponse{$m=$this->membership($r);abort_unless($action->tenant_id===$m->tenant_id&&$action->supplier_id===$m->supplier_id&&$action->company_id===$m->company_id,404);$d=$r->validate(['response'=>'required|string|max:10000','evidence'=>'nullable|array']);$x=SupplierCorrectiveActionResponse::create(['tenant_id'=>$m->tenant_id,'supplier_id'=>$m->supplier_id,'company_id'=>$m->company_id,'corrective_action_id'=>$action->id,'submitted_by'=>$r->user()->id,'response'=>$d['response'],'evidence'=>$d['evidence']??null,'status'=>'submitted']);$action->update(['status'=>'pending_verification']);$audit->record($r,'supplier_portal.corrective_action.response_submitted',$m->tenant_id,$x);return response()->json(['data'=>$x],201);}
    private function poQuery(SupplierPortalMembership $m){return PurchaseOrder::where('tenant_id',$m->tenant_id)->where('supplier_id',$m->supplier_id)->where('company_id',$m->company_id)->whereIn('state',['approved','partially_received','received','closed']);}
    private function released(PurchaseOrder $o,SupplierPortalMembership $m):bool{return (string)$o->tenant_id===$m->tenant_id&&$o->supplier_id===$m->supplier_id&&$o->company_id===$m->company_id&&in_array($o->state,['approved','partially_received','received','closed'],true);}
}
